def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    if n >= 99:
        return 'D'

    opp = [h[1] for h in history]
    me = [h[0] for h in history]
    opp_def = sum(1 for a in opp if a == 'D')
    opp_coop = n - opp_def
    me_def = sum(1 for a in me if a == 'D')
    last_me, last_opp = history[-1]

    # Pure defector: never cooperated
    if opp_coop == 0:
        if n >= 10 and n % 10 == 0:
            return 'C'
        return 'D'

    # Opponent never defected
    if opp_def == 0:
        if n < 5:
            return 'C'
        if n == 5:
            return 'D'
        if me_def == 0:
            return 'C'
        if me_def == 1 and last_me == 'D':
            return 'C'
        return 'D'

    # General case
    if last_opp == 'D':
        consec_opp_def = 0
        for a in reversed(opp):
            if a == 'D':
                consec_opp_def += 1
            else:
                break

        if consec_opp_def == 1 and opp_def == 1:
            return 'C'

        if consec_opp_def >= 3:
            my_consec_c = 0
            for a in reversed(me):
                if a == 'C':
                    my_consec_c += 1
                else:
                    break
            if my_consec_c < 2:
                return 'C'
            else:
                return 'D'

        return 'D'
    else:
        return 'C'
